css:
.loader { position: relative; display: inline-block; width: var(--loader-size); height: var(--loader-size); animation: twScan calc(var(--loader-speed) * 2) ease-in-out infinite; }
.loader .lens { position: absolute; left: 6%; top: 6%; width: 64%; height: 64%; border-radius: 9999px; border: calc(var(--loader-size) * .07) solid var(--loader-color); overflow: hidden; box-sizing: border-box; }
.loader .lens i { position: absolute; left: 0; right: 0; height: calc(var(--loader-size) * .05); background: color-mix(in srgb, var(--loader-color) 60%, transparent); animation: twScanLine calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
.loader::after { content: ''; position: absolute; right: 10%; bottom: 12%; width: 30%; height: calc(var(--loader-size) * .07); border-radius: 9999px; background: var(--loader-color); transform-origin: right center; transform: rotate(45deg); }
@keyframes twScan { 0%, 100% { transform: translate(0, 0); } 50% { transform: translate(7%, 7%); } }
@keyframes twScanLine { 0%, 100% { top: 8%; } 50% { top: 76%; } }
